export const SOCIAL_LINKS=[{id:"instagram1",icon:"fa-brands fa-instagram",label:"Instagram @Ropavejero.Retro",url:"https://www.instagram.com/ropavejero.retro/"},{id:"instagram2",icon:"fa-brands fa-instagram",label:"Instagram @nekketsustore",url:"https://www.instagram.com/nekketsustore/"},{id:"tiktok",icon:"fa-brands fa-tiktok",label:"TikTok",url:""},{id:"youtube",icon:"fa-brands fa-youtube",label:"YouTube",url:""},{id:"facebook",icon:"fa-brands fa-facebook",label:"Facebook",url:""},{id:"threads",icon:"fa-brands fa-threads",label:"Threads",url:""},{id:"x",icon:"fa-brands fa-x-twitter",label:"Twitter / X",url:""},{id:"whatsapp",icon:"fa-brands fa-whatsapp",label:"WhatsApp",url:""},{id:"catalog",icon:"fa-solid fa-table-list",label:"Catálogo Google Sheets",url:"https://docs.google.com/spreadsheets/d/1ekyKZHhUIwQDFtqEblnJN_5SNeYEqOlKOja1wnCutLY"},{id:"github",icon:"fa-brands fa-github",label:"GitHub",url:"https://github.com/Iyov/DoubleImpactStore"}];export function renderSocialLinks(a){if(!a)return;a.forEach(a=>{a&&(a.innerHTML="",SOCIAL_LINKS.filter(a=>a.url&&""!==a.url.trim()).forEach(e=>{const t=document.createElement("a");t.className="social-link",t.href=e.url,t.target="_blank",t.rel="noopener noreferrer",t.setAttribute("aria-label",e.label),t.innerHTML=`<i class="${e.icon}" aria-hidden="true"></i>`,a.appendChild(t)}))});const e=document.getElementById("whatsapp-cta");if(e){const a=SOCIAL_LINKS.find(a=>"whatsapp"===a.id);a&&a.url?(e.href=a.url,e.hidden=!1):e.hidden=!0}}